class Encrypter {
    Map<Character,String> mapping=new HashMap<>();
    Map<String,Integer> frequency=new HashMap<>();
    public Encrypter(char[] keys,String[] values,String[] dictionary){
        for(int i=0;i<keys.length;i++)mapping.put(keys[i],values[i]);
        for(String word:dictionary){
            String encrypted=encrypt(word);
            if(!encrypted.isEmpty())frequency.merge(encrypted,1,Integer::sum);
        }
    }
    public String encrypt(String word1){
        StringBuilder result=new StringBuilder();
        for(char ch:word1.toCharArray()){
            String value=mapping.get(ch);
            if(value==null)return "";
            result.append(value);
        }
        return result.toString();
    }
    public int decrypt(String word2){
        return frequency.getOrDefault(word2,0);
    }
}

code.kotlin:
class Encrypter(keys:CharArray,values:Array<String>,dictionary:Array<String>){
    private val mapping=HashMap<Char,String>();
    private val frequency=HashMap<String,Int>();
    init{
        for(i in keys.indices)mapping[keys[i]]=values[i];
        for(word in dictionary){
            val encrypted=encrypt(word);
            if(encrypted.isNotEmpty())frequency[encrypted]=(frequency[encrypted]?:0)+1
        }
    }
    fun encrypt(word1:String):String{
        val result=StringBuilder();
        for(ch in word1){
            val value=mapping[ch]?:return "";
            result.append(value)
        };
        return result.toString()
    }
    fun decrypt(word2:String)=frequency[word2]?:0
}

code.cpp:
class Encrypter {
    unordered_map<char,string> mapping;
    unordered_map<string,int> frequency;
    public:Encrypter(vector<char>& keys,vector<string>& values,vector<string>& dictionary){
        for(int i=0;i<(int)keys.size();++i)mapping[keys[i]]=values[i];
        for(string& word:dictionary){
            string encrypted=encrypt(word);
            if(!encrypted.empty())++frequency[encrypted];
        }
    }
    string encrypt(string word1){
        string result;
        for(char ch:word1){
            if(!mapping.count(ch))return "";
            result+=mapping[ch];
        }
        return result;
    }
    int decrypt(string word2){
        return frequency[word2];
    }
};
